#[test]
fn max_message_bytes_attribute_and_send_limit() {
    let mut h = Harness::new();
    let attrs = |name: &str| {
        h.run(json!({"Command": "GetQueueAttributes", "QueueName": name}))["Attributes"].clone()
    };
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(attrs("q")["MaxMessageBytes"], 1024);

    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
                "Attributes": {"MaxMessageBytes": 4}}));
    assert_eq!(attrs("q")["MaxMessageBytes"], 4);
    // "é" is two bytes, so "éé" fits and "ééa" does not.
    h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "éé"}));
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "ééa"})),
        "InvalidParameterValue"
    );
    // The limit does not touch messages already queued.
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
                "Attributes": {"MaxMessageBytes": 1}}));
    let got = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(got["Messages"][0]["Body"], "éé");
}

#[test]
fn max_message_bytes_checks_before_send_rules_and_validates_range() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q",
                "Attributes": {"MaxMessageBytes": 2}}));
    // Rule 0 beats the UnsupportedOperation of rule 1.
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "abc", "GroupId": "g"})),
        "InvalidParameterValue"
    );
    for bad in [0, 1025] {
        assert_eq!(
            h.err(json!({"Command": "CreateQueue", "QueueName": "r",
                         "Attributes": {"MaxMessageBytes": bad}})),
            "InvalidParameterValue"
        );
    }
    // It takes part in CreateQueue rule 4.
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q",
                "Attributes": {"MaxMessageBytes": 2}}));
    assert_eq!(
        h.err(json!({"Command": "CreateQueue", "QueueName": "q"})),
        "QueueAlreadyExists"
    );
}
