    assert_eq!(h.err(s(json!([]))), "EmptyBatchRequest");
    let eleven: Vec<Value> = (0..11).map(|i| json!({"Id": format!("i{i}"), "Body": "x"})).collect();
    assert_eq!(h.err(s(Value::Array(eleven))), "TooManyEntriesInBatchRequest");
    // Rule 2 comes before rule 3: eleven bad entries are "too many".
    assert_eq!(h.err(s(Value::Array(vec![json!(1); 11]))), "TooManyEntriesInBatchRequest");
    for bad in [
        json!(["x"]),
        json!([{"Body": "x"}]),
