    }
    // Rule 3 comes before rule 4.
    assert_eq!(
        h.err(s(json!([{"Id": "a"}, {"Id": "a"}, {"Id": 5}]))),
        "InvalidBatchEntryId"
    );
    assert_eq!(
        h.err(s(json!([{"Id": "a", "Body": "x"}, {"Id": "a", "Body": "y"}]))),
        "BatchEntryIdsNotDistinct"
    );
