    let ok = send_batch(&mut h, "q", json!([{"Id": "a", "Body": "x"}, {"Id": "A", "Body": "x"}, {"Id": "z".repeat(80), "Body": "x"}]));
    assert_eq!(ok["Successful"].as_array().unwrap().len(), 3);
    // Ten entries are allowed.
