    assert_eq!(send_batch(&mut h, "q", Value::Array(ten))["Successful"].as_array().unwrap().len(), 10);
    // Nothing from the rejected requests was sent.
    assert_eq!(counts(&mut h, "q")["Visible"], 13);
}

