fn batch_validation_order() {
    let mut h = Harness::new();
    queue(&mut h, "q", json!({}));
    let s = |entries: Value| json!({"Command": "SendMessageBatch", "QueueName": "q", "Entries": entries});
    assert_eq!(h.err(s(json!([]))), "EmptyBatchRequest");
    let eleven: Vec<Value> = (0..11).map(|i| json!({"Id": format!("i{i}"), "Body": "x"})).collect();
    assert_eq!(h.err(s(Value::Array(eleven))), "TooManyEntriesInBatchRequest");
    // Rule 2 comes before rule 3: eleven bad entries are "too many".
    assert_eq!(h.err(s(Value::Array(vec![json!(1); 11]))), "TooManyEntriesInBatchRequest");
    for bad in [
        json!(["x"]),
        json!([{"Body": "x"}]),
        json!([{"Id": null, "Body": "x"}]),
        json!([{"Id": 1, "Body": "x"}]),
        json!([{"Id": "", "Body": "x"}]),
        json!([{"Id": "a b", "Body": "x"}]),
        json!([{"Id": "a".repeat(81), "Body": "x"}]),
        json!([{"Id": "ok", "Body": "x"}, null]),
    ] {
        assert_eq!(h.err(s(bad)), "InvalidBatchEntryId");
    }
    // Rule 3 comes before rule 4.
    assert_eq!(
        h.err(s(json!([{"Id": "a"}, {"Id": "a"}, {"Id": 5}]))),
        "InvalidBatchEntryId"
    );
    assert_eq!(
        h.err(s(json!([{"Id": "a", "Body": "x"}, {"Id": "a", "Body": "y"}]))),
        "BatchEntryIdsNotDistinct"
    );
    // Ids are case-sensitive; 80 characters are fine.
    let ok = send_batch(&mut h, "q", json!([{"Id": "a", "Body": "x"}, {"Id": "A", "Body": "x"}, {"Id": "z".repeat(80), "Body": "x"}]));
    assert_eq!(ok["Successful"].as_array().unwrap().len(), 3);
    // Ten entries are allowed.
    let ten: Vec<Value> = (0..10).map(|i| json!({"Id": format!("i{i}"), "Body": "x"})).collect();
    assert_eq!(send_batch(&mut h, "q", Value::Array(ten))["Successful"].as_array().unwrap().len(), 10);
    // Nothing from the rejected requests was sent.
    assert_eq!(counts(&mut h, "q")["Visible"], 13);
}

