fn earlier_checks_come_first() {
    let mut h = Harness::new();
    let c = |v: Value| h_run(v);
    fn h_run(v: Value) -> Value {
        v
    }
    let _ = c;
    for cmd in ["SendMessageBatch", "DeleteMessageBatch"] {
        assert_eq!(h.err(json!({"Command": cmd, "Entries": []})), "MissingParameter");
        assert_eq!(h.err(json!({"Command": cmd, "QueueName": "q"})), "MissingParameter");
        assert_eq!(h.err(json!({"Command": cmd, "QueueName": "q", "Entries": null})), "MissingParameter");
        assert_eq!(h.err(json!({"Command": cmd, "QueueName": 1, "Entries": []})), "InvalidParameterValue");
        assert_eq!(h.err(json!({"Command": cmd, "QueueName": "q", "Entries": {}})), "InvalidParameterValue");
