    assert_eq!(foreign[0]["ReceiptHandle"], "r-4");

    let r = h.ok(json!({"Command": "DeleteMessageBatch", "QueueName": "q", "Entries": [
        {"Id": "e1", "ReceiptHandle": "r-1"},
        {"Id": "e2", "ReceiptHandle": "r-1"},
